
:root{
  --bg:#0B1220;--bg-2:#141D2E;--bg-3:#070C16;--bg-4:#1A2438;
  --acc:#C6A15A;--acc-2:#E4C98A;--acc-3:#F3E2B8;--acc-soft:rgba(198,161,90,.14);
  --ink:#F7F4EE;--ink-2:#D6D0C4;--ink-3:#9A9388;
  --paper:#F4EEE3;--white:#FBF7F0;--line:#E4D8C4;--text:#141A24;--text-2:#5C6570;--max:1180px;
}
*{margin:0;padding:0;box-sizing:border-box}
html{scroll-behavior:smooth;scroll-padding-top:86px}
body{font-family:'Source Sans 3',sans-serif;color:var(--text);background:linear-gradient(180deg,#FBF7F0 0%,#F4EEE3 42%,#E8DFD0 100%);line-height:1.6;-webkit-font-smoothing:antialiased;min-height:100vh}
h1,h2,h3{font-family:'Manrope',sans-serif;letter-spacing:-.018em;line-height:1.13}
a{color:inherit;text-decoration:none}
.wrap{max-width:var(--max);margin:0 auto;padding:0 28px}
.btn{display:inline-flex;align-items:center;justify-content:center;gap:10px;padding:16px 30px;border-radius:6px;font-family:'Manrope';font-weight:700;font-size:15px;cursor:pointer;border:0;transition:background .2s,border-color .2s,color .2s}
.btn-acc{background:linear-gradient(135deg,#F0D9A2,#C6A15A 55%,#B08A42);color:#0B1220;box-shadow:0 10px 28px -10px rgba(176,138,66,.55)}
.btn-acc:hover{background:linear-gradient(135deg,#F7E6BB,#E4C98A)}
.btn-ghost{background:transparent;color:#0B1220;border:1.5px solid var(--acc)}.btn-ghost:hover{background:linear-gradient(135deg,#F7E6BB,#E4C98A);border-color:var(--acc-2)}
.btn-dark{background:var(--bg);color:#fff}.btn-dark:hover{background:var(--bg-2)}
.sec{padding:100px 0}
.sec-title{font-size:clamp(29px,3.8vw,42px);font-weight:800;color:var(--bg);max-width:20ch;margin-bottom:16px}
.sec-lead{font-size:18.5px;color:var(--text-2);max-width:62ch}
.dark{background:var(--bg);color:var(--ink)}.dark .sec-title{color:#fff}.dark .sec-lead{color:var(--ink-2)}
.nav{position:fixed;inset:0 0 auto;z-index:100;padding:16px 0;transition:background .3s,padding .3s}
.nav.scrolled{background:rgba(251,247,240,.94);backdrop-filter:blur(12px);padding:11px 0;box-shadow:0 8px 28px -16px rgba(20,26,36,.2);border-bottom:1px solid rgba(198,161,90,.22)}
.nav .wrap{max-width:none;display:flex;align-items:center;justify-content:space-between;gap:24px;padding:0 40px}
.logo{display:flex;align-items:center;gap:10px;color:var(--bg);font-family:'Manrope';font-weight:800;font-size:23px;letter-spacing:.06em}

.nav-links{display:flex;flex:1;justify-content:space-evenly;list-style:none;margin:0 32px}
.nav-links a{color:var(--text);font-weight:600;font-size:16px;padding:8px 14px;display:inline-block}.nav-links a:hover{color:var(--acc)}
.nav-right{display:flex;align-items:center;gap:16px}
.nav-cta{padding:11px 20px;font-size:13.5px}
.lang{display:flex;border:1px solid rgba(198,161,90,.45);border-radius:6px;overflow:hidden}
.lang button{background:none;border:0;color:var(--text);padding:8px 11px;font-family:'Manrope';font-weight:700;font-size:12px;cursor:pointer}
.lang button.on{background:linear-gradient(135deg,#E4C98A,#C6A15A);color:#0B1220}
.burger{display:none;background:none;border:0;color:var(--bg);font-size:26px;cursor:pointer}
.hero{position:relative;min-height:100vh;display:flex;align-items:center;background:#FBF7F0;color:var(--text);overflow:hidden}
.hero-bg{position:absolute;inset:0;background:url(data:image/jpeg;base64,) center/cover no-repeat}
@media(max-width:760px){.hero-bg{background-image:url(data:image/jpeg;base64,)}}
.hero-bg::after{content:"";position:absolute;inset:0;background:linear-gradient(100deg,#FBF7F0 0%,rgba(251,247,240,.96) 36%,rgba(251,247,240,.7) 58%,rgba(251,247,240,.42) 100%)}
.hero::after{content:"";position:absolute;inset:0;z-index:1;pointer-events:none;background:linear-gradient(180deg,rgba(251,247,240,.28) 0%,transparent 30%,rgba(251,247,240,.18) 100%)}
.hero .wrap{position:relative;z-index:2;max-width:none;width:100%;margin:0;padding:130px 8% 80px clamp(16px,2.2vw,32px)}
.hero-kicker{display:inline-flex;align-items:center;gap:10px;color:var(--acc);font-family:'Manrope';font-weight:700;font-size:13.5px;margin-bottom:24px}
.hero-kicker::before{content:"";width:32px;height:2px;background:var(--acc)}
.hero h1{font-size:clamp(36px,4.6vw,58px);font-weight:800;max-width:16ch;margin-bottom:22px;color:var(--bg)}
.hero p{font-size:19px;color:var(--text-2);max-width:46ch;margin-bottom:36px}
.hero-cta{display:flex;gap:14px;flex-wrap:wrap}
.stats{background:var(--bg-3);border-top:1px solid rgba(255,255,255,.09)}
.stats .wrap{display:grid;grid-template-columns:repeat(4,1fr)}
.stat{padding:34px 26px 34px 0;border-right:1px solid rgba(255,255,255,.09)}
.stat:last-child{border-right:0}
.stat b{display:block;font-family:'Manrope';font-size:34px;font-weight:800;color:var(--acc-2);line-height:1;margin-bottom:8px}
.stat i{display:block;font-style:normal;font-family:'Manrope';font-weight:700;font-size:14.5px;color:#fff;margin-bottom:6px}
.stat span{display:block;color:var(--ink-3);font-size:13.5px;line-height:1.5}
.paths{background:linear-gradient(180deg,#FBF7F0 0%,#F4EEE3 100%)}
.paths-grid{display:grid;grid-template-columns:1fr 1fr;gap:26px;margin-top:46px}
.path{position:relative;border-radius:14px;overflow:hidden;min-height:330px;display:flex;align-items:flex-end;color:#fff;background:var(--bg)}
.path img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;opacity:.5}
.path-body{position:relative;z-index:2;padding:36px;background:linear-gradient(180deg,transparent 15%,rgba(10,20,36,.55) 45%,rgba(10,20,36,.97) 100%);width:100%}
.path h3{font-size:26px;font-weight:800;margin-bottom:10px}
.path p{color:var(--ink-2);font-size:16px;margin-bottom:20px;max-width:38ch}
.path .btn-ghost{color:#fff;border-color:rgba(255,255,255,.4)}
.serv-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:24px;margin-top:48px}
.serv{background:linear-gradient(160deg,var(--bg-4),var(--bg-2));border:1px solid rgba(230,210,168,.14);border-radius:14px;padding:34px;position:relative;overflow:hidden}
.serv::before{content:"";position:absolute;top:0;left:0;width:100%;height:3px;background:linear-gradient(90deg,var(--acc-3),var(--acc-2),var(--acc-3));border-radius:12px 12px 0 0}
.serv h3{font-size:21px;font-weight:800;color:#fff;margin-bottom:16px}
.serv ul{list-style:none;display:grid;gap:11px}
.serv li{display:flex;gap:11px;font-size:15.5px;color:var(--ink-2)}
.serv li::before{content:"";flex:0 0 7px;height:7px;border-radius:50%;background:var(--acc);margin-top:9px}
.serv-note{margin-top:32px;padding:22px 26px;background:var(--acc-soft);border-left:3px solid var(--acc);border-radius:0 8px 8px 0;color:var(--ink);font-size:16.5px}
.about{background:linear-gradient(180deg,#FBF7F0 0%,#F4EEE3 100%)}
.about .wrap{display:grid;grid-template-columns:1fr 1.02fr;gap:62px;align-items:center}
.about-img{position:relative;border-radius:12px;overflow:hidden;min-height:490px;background:var(--bg)}
.about-img img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover}
.about-badge{position:absolute;left:22px;bottom:22px;background:linear-gradient(135deg,var(--acc-2),var(--acc));box-shadow:0 12px 30px -12px rgba(0,0,0,.5);color:var(--bg);padding:16px 20px;border-radius:8px;font-family:'Manrope';font-weight:800;font-size:14px;line-height:1.3}
.about-badge b{display:block;font-size:32px}
.about p{font-size:17px;color:var(--text-2);margin-bottom:15px}
.about .lead{font-size:18.5px;color:var(--text);font-weight:500}
.values{background:linear-gradient(180deg,#F4EEE3 0%,#E8DFD0 100%)}
.val-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:22px;margin-top:46px}
.val{background:#FBF7F0;border:1px solid rgba(198,161,90,.22);border-radius:12px;padding:30px;box-shadow:0 2px 14px -8px rgba(20,26,36,.14);transition:transform .25s,box-shadow .25s}
.val:hover{transform:translateY(-3px);box-shadow:0 18px 40px -22px rgba(20,26,36,.35)}
.val-ico{width:52px;height:52px;border-radius:12px;background:linear-gradient(160deg,#F0D9A2,#C6A15A 55%,#B08A42);border:1px solid rgba(198,161,90,.28);display:grid;place-items:center;color:#0B1220;margin-bottom:18px}
.val-ico svg{width:24px;height:24px;display:block}
.val h3{font-size:18.5px;color:var(--bg);margin-bottom:9px;font-weight:800}
.val p{color:var(--text-2);font-size:15.5px}
.process{background:linear-gradient(180deg,#FBF7F0 0%,#F4EEE3 100%)}
.steps{display:grid;grid-template-columns:repeat(4,1fr);gap:22px;margin-top:48px;counter-reset:s}
.step{border-top:2px solid var(--acc);padding-top:24px}
.step::before{counter-increment:s;content:"0" counter(s);font-family:'Manrope';font-weight:800;font-size:15px;color:var(--acc);display:block;margin-bottom:12px;letter-spacing:.08em}
.step h3{font-size:19px;color:var(--bg);margin-bottom:10px;font-weight:800}
.step p{color:var(--text-2);font-size:15px}
.quote{background:var(--bg);color:#fff;text-align:center;border-top:1px solid rgba(228,201,138,.22);border-bottom:1px solid rgba(228,201,138,.12)}
.quote .wrap{max-width:880px}
.quote h2{font-size:clamp(26px,3.4vw,38px);font-weight:800;margin-bottom:22px}
.quote p{font-size:17.5px;color:var(--ink-2);margin-bottom:16px}
.forms{background:linear-gradient(180deg,#F4EEE3 0%,#E8DFD0 100%)}
.tabs{display:flex;gap:10px;margin:42px 0 24px;flex-wrap:wrap}
.tab{padding:14px 26px;border-radius:8px;border:1.5px solid var(--line);background:#fff;font-family:'Manrope';font-weight:700;font-size:15.5px;color:var(--text-2);cursor:pointer;transition:.2s}
.tab.on{background:var(--bg);color:#fff;border-color:var(--bg)}
.panel{display:none;background:#FBF7F0;border:1px solid rgba(198,161,90,.28);border-radius:14px;padding:40px;box-shadow:0 20px 50px -35px rgba(20,26,36,.4)}
.panel.on{display:block}
.f-row{display:grid;grid-template-columns:1fr 1fr;gap:16px}
.f{display:flex;flex-direction:column;gap:6px;margin-bottom:16px}
.f label{font-size:13.5px;font-weight:600;color:var(--text-2)}
.f input,.f select,.f textarea{font-family:inherit;font-size:15.5px;padding:13px 14px;border:1.5px solid var(--line);border-radius:6px;background:#FBF7F0}
.f input:focus,.f select:focus,.f textarea:focus{outline:0;border-color:var(--acc);background:#fff}
.f textarea{min-height:100px;resize:vertical}
.panel .btn{width:100%;margin-top:8px}
.f-note{font-size:12.5px;color:var(--ink-3);margin-top:12px;text-align:center}
.f-ok{display:none;background:var(--acc-soft);border:1px solid var(--acc);border-radius:8px;padding:20px;color:var(--bg);font-weight:600;text-align:center}
.contact{position:relative;overflow:hidden;min-height:100vh;color:var(--ink);background:var(--bg);display:flex;align-items:center;padding:100px 0}
.contact-bg{position:absolute;inset:0;background:url(data:image/jpeg;base64,) 58% 46%/cover no-repeat}
.contact-bg::after{content:"";position:absolute;inset:0;background:linear-gradient(90deg,rgba(8,14,28,.72) 0%,rgba(8,14,28,.38) 34%,rgba(8,14,28,.12) 58%,rgba(8,14,28,.06) 100%)}
.contact .wrap{position:relative;z-index:2;width:100%}
.contact-main h2{font-size:clamp(30px,4vw,46px);font-weight:800;color:#fff;max-width:16ch;margin-bottom:16px;text-shadow:0 8px 28px rgba(0,0,0,.35)}
.contact-main p{font-size:18px;color:var(--ink);max-width:42ch;margin-bottom:28px;line-height:1.55;text-shadow:0 4px 18px rgba(0,0,0,.35)}
.contact-cta-top{margin-bottom:24px}
.contact-meta{margin-top:42px}
.c-item{display:flex;gap:15px;margin-bottom:16px}
.c-ico{flex:0 0 44px;height:44px;border-radius:8px;background:rgba(8,16,30,.45);border:1px solid rgba(255,255,255,.16);display:grid;place-items:center;color:var(--acc-2);font-size:16px}
.c-item b{display:block;font-family:'Manrope';font-size:12.5px;letter-spacing:.07em;color:var(--ink-2);margin-bottom:3px}
.c-item a,.c-item span{color:#fff;font-size:16.5px;font-weight:500}
.legal{position:absolute;top:18px;right:18px;z-index:3;background:rgba(8,16,30,.62);border:1px solid rgba(255,255,255,.16);backdrop-filter:blur(14px);border-radius:12px;padding:26px;max-width:340px}
.legal b{display:block;font-family:'Manrope';font-weight:800;color:#fff;font-size:16.5px;margin-bottom:14px}
.legal div{display:flex;justify-content:space-between;padding:9px 0;border-bottom:1px solid rgba(255,255,255,.08);font-size:15px;color:var(--ink-2)}
.legal div:last-child{border:0}
.legal em{font-style:normal;color:#fff;font-weight:600}
footer{background:#05080F;color:var(--ink-3);padding:30px 0;font-size:14px;border-top:1px solid rgba(228,201,138,.14)}
footer .wrap{display:flex;justify-content:space-between;align-items:center;gap:18px;flex-wrap:wrap}
@media(max-width:1000px){
 .nav{padding:14px 0}
 .nav.scrolled{padding:10px 0}
 .nav .wrap{padding:0 22px}
 .nav-links{display:none}.burger{display:block}
 .nav-right{gap:8px}
 .nav-cta{display:none}
 .lang button{padding:8px 10px;font-size:12px}
 .logo-mark{height:44px}
 .nav.scrolled .logo-mark{height:38px}
 .nav.open .nav-links{display:flex;position:absolute;top:100%;left:0;right:0;background:#FBF7F0;flex-direction:column;padding:20px 28px;gap:16px;border-bottom:1px solid rgba(198,161,90,.22)}
 .stats .wrap{grid-template-columns:1fr 1fr}.stat{border-right:0;border-bottom:1px solid rgba(255,255,255,.09);padding-right:0}
 .paths-grid,.serv-grid,.val-grid,.about .wrap,.contact .wrap{grid-template-columns:1fr}
 .steps{grid-template-columns:1fr 1fr}.sec{padding:74px 0}.about-img{min-height:330px}
}
@media(max-width:520px){
 .nav .wrap{gap:12px}
 .lang button{padding:7px 8px;font-size:11px}
 .logo-mark{height:38px}
 .burger{font-size:24px}
}
@media(max-width:1000px){html{scroll-padding-top:74px}}
@media(max-width:560px){.steps,.f-row{grid-template-columns:1fr}.panel{padding:26px 20px}.hero p{font-size:17.5px}}
@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}*{transition:none!important}}
/* AREAS */
.areas{background:linear-gradient(180deg,#F4EEE3 0%,#E8DFD0 100%)}
.areas-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:24px;margin-top:46px}
.area{position:relative;border-radius:12px;overflow:hidden;min-height:380px;background:var(--bg);color:#fff;display:flex;align-items:flex-end}
.area img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;opacity:.62}
.area-body{position:relative;z-index:2;padding:30px;width:100%;background:linear-gradient(180deg,transparent 22%,rgba(15,27,49,.96))}
.area h3{font-size:22px;font-weight:800;margin-bottom:8px}
.area p{color:var(--ink-2);font-size:15.5px}
@media(max-width:1000px){.areas-grid{grid-template-columns:1fr}.area{min-height:300px}}

/* ===== MOBILE / TABLET POLISH ===== */
@media(max-width:1000px){
  .sec{padding:64px 0}
  .wrap{padding:0 22px}
  .sec-title{font-size:clamp(26px,6vw,34px);max-width:100%}
  .sec-lead{font-size:17px}
  .hero .wrap{padding:112px 20px 64px 16px}
  .hero h1{font-size:clamp(32px,8vw,44px);max-width:100%}
  .hero p{font-size:17.5px}
  .hero-cta{gap:10px}
  .hero-cta .btn{flex:1 1 100%;padding:15px 22px}
  .stat{padding:24px 18px 24px 0}
  .stat b{font-size:29px}
  .about-img{min-height:300px;order:-1}
  .about .wrap{gap:34px}
  .serv{padding:28px}
  .val{padding:26px}
  .tabs .tab{flex:1 1 100%;text-align:center}
  .legal{max-width:300px}
  .c-item a,.c-item span{font-size:16px;word-break:break-word}
}
@media(max-width:640px){
  .legal{position:static;max-width:none;margin:24px 18px 0}
  .sec{padding:54px 0}
  .wrap{padding:0 18px}
  .hero{min-height:auto}
  .hero .wrap{padding:104px 16px 56px}
  .hero h1{font-size:clamp(29px,8.6vw,38px);line-height:1.16}
  .hero p{font-size:16.5px;margin-bottom:28px}
  .stats .wrap{grid-template-columns:1fr}
  .stat{padding:20px 0;text-align:left}
  .stat b{font-size:26px;margin-bottom:5px}
  .stat i{font-size:14px}.stat span{font-size:13px}
  .path{min-height:280px}.path-body{padding:26px 22px}
  .path h3{font-size:22px}.path p{font-size:15px}
  .path .btn{width:100%}
  .area{min-height:270px}
  .serv{padding:24px 22px}.serv h3{font-size:19px}
  .serv-note{padding:18px 20px;font-size:15.5px}
  .about-badge{left:16px;bottom:16px;padding:13px 16px}
  .about-badge b{font-size:27px}
  .steps{gap:18px}
  .quote h2{font-size:clamp(23px,6.6vw,30px)}
  .quote p{font-size:16px}
  .panel{padding:24px 18px;border-radius:12px}
  .f input,.f select,.f textarea{font-size:16px} /* 16px = iOS не зумить */
  .legal{padding:22px}
  .legal div{font-size:14px}
  footer .wrap{flex-direction:column;align-items:flex-start;gap:10px;text-align:left}
  .logo{font-size:20px}
}
/* тач-таргети */
@media(hover:none){
  .btn{min-height:48px}
  .nav-links a{padding:6px 0;display:inline-block}
  .lang button{min-width:42px;min-height:38px}
}

/* logo */


/* logo image */
.logo{display:flex;align-items:center}
.logo-mark{height:52px;width:auto;display:block;max-width:240px;object-fit:contain}
.nav.scrolled .logo-mark{height:42px;max-width:200px}
footer .logo-mark{height:40px;max-width:180px}

/* TRUCK CTA (merged into contact) */
@media(max-width:760px){
  .contact{min-height:auto;padding:72px 0}
  .contact-bg{background-position:70% center}
  .contact-bg::after{background:linear-gradient(180deg,rgba(8,14,28,.55),rgba(8,14,28,.82))}
  .contact-main h2{max-width:none}
  .contact-meta{margin-top:28px}
}


/* ===== MOBILE HERO + NAV FIX ===== */
@media(max-width:760px){
  .hero{background:var(--bg);color:#fff;min-height:auto;display:block}
  .hero .wrap{padding:100px 22px 40px;max-width:100%}
  .hero-bg{background-position:center;top:auto;bottom:0;height:300px}
  .hero-bg::after{background:linear-gradient(180deg,var(--bg) 0%,rgba(18,30,52,.5) 38%,transparent 72%)!important}
  .hero-kicker{color:var(--acc-2)!important}
  .hero h1{color:#fff!important;max-width:100%;font-size:clamp(30px,8vw,42px)}
  .hero p{color:var(--ink-2)!important;max-width:100%}
  .hero-cta{margin-bottom:280px;flex-wrap:wrap}
  .hero-cta .btn{flex:1 1 100%;justify-content:center}
  .nav:not(.scrolled) .nav-links a,.nav:not(.scrolled) .burger{color:#fff!important}
  .nav:not(.scrolled) .logo-mark{content:url('img/logo-white.png')!important}
  .nav:not(.scrolled) .lang button{color:var(--ink-2)!important}
  .nav:not(.scrolled) .lang button.on{color:var(--bg)!important}
  .nav:not(.scrolled){background:rgba(18,30,52,.4);backdrop-filter:blur(4px)}
}

/* ===== MOBILE FIX (телефон) ===== */
@media(max-width:760px){
  .hero{background:var(--bg);color:#fff;min-height:auto;display:block}
  .hero .wrap{padding:100px 22px 40px;max-width:100%;width:100%;margin:0}
  .hero-bg{top:auto;bottom:0;height:300px;background-position:center bottom}
  .hero-bg::after{background:linear-gradient(180deg,var(--bg) 0%,rgba(18,30,52,.5) 40%,transparent 72%)!important}
  .hero-kicker{color:var(--acc-2)!important}
  .hero h1{color:#fff!important;max-width:100%;font-size:clamp(30px,8vw,42px)}
  .hero p{color:var(--ink-2)!important;max-width:100%}
  .hero-cta{margin-bottom:280px;flex-wrap:wrap}
  .hero-cta .btn{flex:1 1 100%;justify-content:center}
  .legal{position:static!important;max-width:100%!important;margin-top:24px}
  .nav:not(.scrolled) .nav-links a,.nav:not(.scrolled) .burger{color:#fff!important}
  .nav:not(.scrolled) .lang button{color:var(--ink-2)!important}
  .nav:not(.scrolled){background:rgba(18,30,52,.42);backdrop-filter:blur(4px)}
}

/* ==========================================================================
   ESCOBA — RESPONSIVE LAYER 2026
   Non-destructive overrides for phones, tablets, laptops and wide screens.
   Mobile/tablet banner uses the user-provided third image.
   ========================================================================== */
html{-webkit-text-size-adjust:100%;text-size-adjust:100%}
body{overflow-x:clip}
img,svg,video{max-width:100%}
button,input,select,textarea{max-width:100%}
.wrap{width:min(100%,calc(var(--max) + 56px))}
.logo{min-width:0;flex:0 0 auto}
.logo-mark{display:block;width:auto;height:clamp(40px,4.2vw,58px);max-width:min(240px,27vw);object-fit:contain}
.nav:not(.scrolled) .logo-mark{content:url("data:image/png;base64,")!important}
.nav.scrolled .logo-mark{content:url("data:image/png;base64,")!important}
.nav:not(.scrolled){background:linear-gradient(180deg,rgba(11,18,32,.86),rgba(11,18,32,.48),transparent)}
.nav:not(.scrolled) .nav-links a,.nav:not(.scrolled) .burger{color:#fff}
.nav:not(.scrolled) .lang button{color:#fff}
.nav:not(.scrolled) .lang button.on{color:#0B1220}
.hero .wrap,.contact .wrap{min-width:0}
.path,.area,.serv,.val,.step,.panel,.about-img{min-width:0}
.f input,.f select,.f textarea{width:100%;min-width:0}

/* Large laptops / compact desktop */
@media (max-width:1280px){
  .nav .wrap{padding-inline:24px;gap:16px}
  .nav-links{margin-inline:12px}
  .nav-links a{font-size:14px;padding-inline:9px}
  .nav-right{gap:10px}
  .nav-cta{padding-inline:16px}
}

/* Tablet and below */
@media (max-width:1000px){
  html{scroll-padding-top:76px}
  .nav{padding:10px 0;background:rgba(11,18,32,.92)!important;backdrop-filter:blur(12px);-webkit-backdrop-filter:blur(12px);border-bottom:1px solid rgba(255,255,255,.08)}
  .nav.scrolled{padding:9px 0;background:rgba(251,247,240,.96)!important}
  .nav .wrap{width:100%;padding-inline:18px;gap:12px}
  .logo-mark{height:42px;max-width:150px}
  .nav.scrolled .logo-mark{height:39px}
  .nav-links{display:none!important;margin:0}
  .burger{display:grid!important;place-items:center;width:42px;height:42px;font-size:25px;line-height:1;border-radius:7px;color:#fff}
  .nav.scrolled .burger{color:var(--bg)}
  .nav-right{gap:8px;margin-left:auto}
  .nav-cta{display:none!important}
  .lang{flex:0 0 auto}
  .lang button{min-width:38px;height:38px;padding:0 9px}
  .nav.open .nav-links{display:flex!important;position:absolute;top:100%;left:0;right:0;max-height:calc(100dvh - 64px);overflow:auto;background:rgba(251,247,240,.985);flex-direction:column;padding:16px 20px 22px;gap:2px;border-bottom:1px solid rgba(198,161,90,.3);box-shadow:0 18px 35px -25px rgba(11,18,32,.45)}
  .nav.open .nav-links a{display:block;color:var(--text)!important;font-size:16px;padding:12px 8px;border-bottom:1px solid rgba(20,26,36,.06)}
  .wrap{width:100%;padding-inline:22px}
  .sec{padding:clamp(58px,8vw,78px) 0}
  .sec-title{font-size:clamp(28px,5.5vw,38px)}
  .sec-lead{font-size:clamp(16px,2.2vw,18px)}
  .paths-grid,.serv-grid,.val-grid,.about .wrap,.contact .wrap{grid-template-columns:1fr}
  .areas-grid{grid-template-columns:1fr}
  .steps{grid-template-columns:repeat(2,minmax(0,1fr))}
  .about-img{min-height:clamp(320px,58vw,520px)}
  .contact{min-height:auto;padding:80px 0}
  .legal{position:static!important;max-width:520px!important;margin-top:28px}

  /* Tablet hero: content and requested banner side-by-side */
  .hero{min-height:720px;display:grid;grid-template-columns:minmax(0,46%) minmax(0,54%);align-items:stretch;background:var(--bg);color:#fff}
  .hero::after{display:none}
  .hero-bg{position:relative;inset:auto;grid-column:2;grid-row:1;height:100%;min-height:720px;background-image:url("data:image/png;base64,")!important;background-size:cover!important;background-repeat:no-repeat!important;background-position:center center!important}
  .hero-bg::after{content:"";position:absolute;inset:0;background:linear-gradient(90deg,var(--bg) 0%,rgba(11,18,32,.5) 22%,rgba(11,18,32,.05) 60%,transparent 100%)!important}
  .hero .wrap{grid-column:1;grid-row:1;align-self:center;width:100%;padding:120px 22px 74px;z-index:2}
  .hero-kicker{color:var(--acc-2)!important}
  .hero h1{font-size:clamp(34px,5vw,48px);color:#fff!important;max-width:12ch}
  .hero p{font-size:17px;color:var(--ink-2)!important;max-width:35ch}
  .hero .btn-ghost{color:#fff;border-color:rgba(255,255,255,.45)}
  .hero-cta{margin-bottom:0!important;gap:10px}
  .hero-cta .btn{flex:1 1 190px;padding-inline:18px}
}

/* Phones */
@media (max-width:760px){
  .nav .wrap{padding-inline:14px}
  .logo-mark{height:auto!important;width:clamp(104px,31vw,138px);max-width:none}
  .hero{display:flex;flex-direction:column;min-height:auto;background:var(--bg);overflow:hidden}
  .hero .wrap{order:1;width:100%;margin:0;padding:104px 20px 34px;position:relative}
  .hero-bg{order:2;position:relative;inset:auto;width:100%;height:auto!important;min-height:0;aspect-ratio:618/758;background-image:url("data:image/png;base64,")!important;background-size:cover!important;background-position:center center!important;background-repeat:no-repeat!important}
  .hero-bg::after{background:linear-gradient(180deg,rgba(11,18,32,.28) 0%,transparent 22%)!important}
  .hero h1{font-size:clamp(31px,9.2vw,42px);max-width:100%;margin-bottom:18px}
  .hero p{font-size:clamp(16px,4.5vw,18px);max-width:100%;margin-bottom:28px}
  .hero-kicker{margin-bottom:18px}
  .hero-cta{margin:0!important;display:grid;grid-template-columns:1fr;gap:10px}
  .hero-cta .btn{width:100%;min-height:50px}
  .stats .wrap{grid-template-columns:repeat(2,minmax(0,1fr));padding-inline:20px}
  .stat{padding:26px 12px 26px 0;min-width:0}
  .stat b{font-size:30px}
  .paths-grid,.areas-grid,.serv-grid,.val-grid{gap:18px;margin-top:34px}
  .path{min-height:300px}
  .path-body{padding:26px 22px}
  .area{min-height:300px}
  .area-body{padding:24px 22px}
  .serv,.val{padding:26px 22px}
  .steps{grid-template-columns:1fr;gap:28px;margin-top:36px}
  .f-row{grid-template-columns:1fr}
  .panel{padding:28px 20px}
  .tabs{display:grid;grid-template-columns:1fr 1fr;margin-top:30px}
  .tab{padding:12px 10px;font-size:14px}
  .contact-main h2{font-size:clamp(29px,8vw,38px);max-width:100%}
  .contact-main p{font-size:17px}
  footer .wrap{flex-direction:column;align-items:flex-start;padding-inline:20px}
}

/* Small phones, including 320–390px */
@media (max-width:430px){
  .nav .wrap{padding-inline:10px;gap:6px}
  .logo-mark{width:clamp(92px,29vw,118px)}
  .nav-right{gap:4px}
  .lang button{min-width:32px;width:32px;height:34px;padding:0;font-size:10px}
  .burger{width:36px;height:36px;font-size:22px}
  .hero .wrap{padding:92px 16px 28px}
  .wrap{padding-inline:16px}
  .sec{padding:54px 0}
  .sec-title{font-size:clamp(26px,8vw,32px)}
  .hero h1{font-size:clamp(29px,9.5vw,38px)}
  .hero p{font-size:16px}
  .stats .wrap{padding-inline:16px}
  .stat{padding-block:22px}
  .stat b{font-size:27px}
  .stat i{font-size:13.5px}
  .stat span{font-size:12.5px}
  .tabs{grid-template-columns:1fr}
  .panel{padding:24px 16px}
  .legal{padding:20px 16px}
  .c-item{gap:11px}
  .c-item a,.c-item span{font-size:15.5px;overflow-wrap:anywhere}
}

/* Very narrow screens */
@media (max-width:350px){
  .logo-mark{width:82px}
  .lang button{min-width:29px;width:29px;font-size:9.5px}
  .burger{width:32px;height:34px}
  .hero .wrap{padding-top:88px}
  .stats .wrap{grid-template-columns:1fr}
  .stat{border-bottom:1px solid rgba(255,255,255,.09)}
}

/* Landscape phones / short viewports */
@media (max-width:900px) and (orientation:landscape) and (max-height:520px){
  .hero{display:grid;grid-template-columns:1fr 1fr;min-height:520px}
  .hero .wrap{grid-column:1;grid-row:1;order:initial;padding:88px 18px 36px;align-self:center}
  .hero-bg{grid-column:2;grid-row:1;order:initial;height:100%!important;min-height:520px;aspect-ratio:auto}
  .hero h1{font-size:clamp(27px,5vw,36px)}
  .hero p{font-size:15px;margin-bottom:20px}
  .hero-kicker{margin-bottom:12px}
}

@media (min-width:1800px){
  :root{--max:1380px}
  .hero .wrap{padding-left:max(36px,calc((100vw - 1500px)/2))}
  .sec{padding:118px 0}
}

@supports (height:100svh){
  @media (min-width:1001px){.hero{min-height:100svh}}
}

/* Responsive banner WHITE FADE — visible on the adaptive hero image */
@media (max-width:1000px){
  .hero::after{display:none!important}
  .hero-bg{position:relative;overflow:hidden}
  .hero-bg::after{
    content:""!important;
    display:block!important;
    position:absolute!important;
    inset:0!important;
    z-index:1!important;
    pointer-events:none!important;
    background:linear-gradient(90deg,
      rgba(251,247,240,.96) 0%,
      rgba(251,247,240,.88) 20%,
      rgba(251,247,240,.62) 42%,
      rgba(251,247,240,.28) 66%,
      rgba(251,247,240,.06) 88%,
      rgba(251,247,240,0) 100%)!important;
  }
}
@media (max-width:760px){
  .hero-bg::after{
    background:linear-gradient(180deg,
      rgba(251,247,240,.92) 0%,
      rgba(251,247,240,.78) 14%,
      rgba(251,247,240,.52) 30%,
      rgba(251,247,240,.24) 48%,
      rgba(251,247,240,.07) 64%,
      rgba(251,247,240,0) 80%)!important;
  }
}
@media (max-width:900px) and (orientation:landscape) and (max-height:520px){
  .hero-bg::after{
    background:linear-gradient(90deg,
      rgba(251,247,240,.92) 0%,
      rgba(251,247,240,.72) 24%,
      rgba(251,247,240,.34) 52%,
      rgba(251,247,240,.08) 76%,
      rgba(251,247,240,0) 100%)!important;
  }
}




/* ===== FINAL FIX: WHITE EFFECT ACROSS THE WHOLE RESPONSIVE HERO ===== */
/* Tablet: the third banner photo fills the complete hero, while the white wash
   covers the full banner (not only the image area). */
@media (max-width:1000px){
  .hero{
    position:relative!important;
    display:flex!important;
    align-items:center!important;
    min-height:clamp(680px,92vh,900px)!important;
    background:#FBF7F0!important;
    color:#0B1220!important;
    overflow:hidden!important;
  }
  .hero-bg{
    position:absolute!important;
    inset:0!important;
    width:100%!important;
    height:100%!important;
    min-height:0!important;
    grid-column:auto!important;
    grid-row:auto!important;
    background-position:center center!important;
    background-size:cover!important;
    z-index:0!important;
  }
  .hero-bg::after{
    display:none!important;
  }
  .hero::after{
    content:""!important;
    display:block!important;
    position:absolute!important;
    inset:0!important;
    z-index:1!important;
    pointer-events:none!important;
    background:linear-gradient(100deg,
      rgba(251,247,240,.98) 0%,
      rgba(251,247,240,.96) 34%,
      rgba(251,247,240,.84) 55%,
      rgba(251,247,240,.58) 73%,
      rgba(251,247,240,.30) 88%,
      rgba(251,247,240,.18) 100%)!important;
  }
  .hero .wrap{
    position:relative!important;
    z-index:2!important;
    width:100%!important;
    max-width:100%!important;
    margin:0!important;
  }
  .hero h1{color:#0B1220!important}
  .hero p{color:#42506A!important}
  .hero-kicker{color:#B8892F!important}
}

/* Phones: same full-banner treatment, with the strongest white layer behind
   the copy and a gradual reveal of the photo toward the bottom. */
@media (max-width:760px){
  .hero{
    min-height:clamp(720px,100svh,900px)!important;
    display:flex!important;
    align-items:flex-start!important;
  }
  .hero-bg{
    position:absolute!important;
    inset:0!important;
    height:100%!important;
    /* Show the COMPLETE portrait banner on phones: no cropping.
       The image keeps its aspect ratio, spans the full hero width and is
       anchored to the bottom; the cream hero background fills any space
       above it naturally. */
    background-position:center bottom!important;
    background-size:100% auto!important;
    background-repeat:no-repeat!important;
    background-color:#FBF7F0!important;
  }
  .hero::after{
    background:linear-gradient(180deg,
      rgba(251,247,240,.99) 0%,
      rgba(251,247,240,.98) 22%,
      rgba(251,247,240,.95) 47%,
      rgba(251,247,240,.84) 62%,
      rgba(251,247,240,.58) 76%,
      rgba(251,247,240,.28) 90%,
      rgba(251,247,240,.14) 100%)!important;
  }
  .hero .wrap{
    padding:104px 16px 46px!important;
  }
  .hero-cta{
    margin:0!important;
  }
  .hero h1{color:#0B1220!important}
  .hero p{color:#42506A!important}
  .hero-kicker{color:#B8892F!important}
}

/* Very small phones: keep the entire hero readable without introducing
   a separate photo block. */
@media (max-width:430px){
  .hero{min-height:clamp(700px,100svh,860px)!important}
  .hero-bg{background-size:100% auto!important;background-position:center bottom!important;background-repeat:no-repeat!important}
  .hero .wrap{padding:96px 14px 38px!important}
  .hero::after{
    background:linear-gradient(180deg,
      rgba(251,247,240,.99) 0%,
      rgba(251,247,240,.98) 26%,
      rgba(251,247,240,.94) 52%,
      rgba(251,247,240,.80) 67%,
      rgba(251,247,240,.50) 80%,
      rgba(251,247,240,.22) 93%,
      rgba(251,247,240,.12) 100%)!important;
  }
}




/* Final mobile hero correction: show the entire supplied portrait banner without cropping. */
@media (max-width:760px){
  .hero{height:auto!important;min-height:0!important;overflow:visible!important}
  .hero-bg{
    position:relative!important;
    width:100%!important;
    height:auto!important;
    min-height:0!important;
    aspect-ratio:618 / 758!important;
    background-size:contain!important;
    background-position:center center!important;
    background-repeat:no-repeat!important;
    flex:none!important;
  }
  /* Keep the white wash across the complete hero, not only the image. */
  .hero::after{
    display:block!important;
    content:""!important;
    position:absolute!important;
    inset:0!important;
    z-index:1!important;
    pointer-events:none!important;
    background:linear-gradient(180deg,
      rgba(251,247,240,.97) 0%,
      rgba(251,247,240,.94) 34%,
      rgba(251,247,240,.78) 55%,
      rgba(251,247,240,.38) 76%,
      rgba(251,247,240,.08) 100%)!important;
  }
  .hero-bg::after{display:none!important}
  .hero>.wrap{position:relative!important;z-index:2!important}
}
@media (max-width:430px){
  .hero-bg{aspect-ratio:618 / 758!important;background-size:contain!important;background-position:center center!important}
}



/* FINAL: white/light navigation only on tablet/mobile */
@media (max-width: 1000px) {
  .nav,
  .nav:not(.scrolled),
  .nav.scrolled {
    background: rgba(251,247,240,.96) !important;
    -webkit-backdrop-filter: blur(14px);
    backdrop-filter: blur(14px);
    border-bottom: 1px solid rgba(198,161,90,.20) !important;
    box-shadow: 0 8px 28px -18px rgba(20,26,36,.24) !important;
  }
  .nav .logo-mark,
  .nav:not(.scrolled) .logo-mark,
  .nav.scrolled .logo-mark {
    content: url("data:image/png;base64,") !important;
  }
  .nav .burger,
  .nav:not(.scrolled) .burger,
  .nav.scrolled .burger {
    color: #0B1220 !important;
  }
  .nav .lang {
    background: rgba(255,255,255,.38);
    border-color: rgba(198,161,90,.52) !important;
  }
  .nav .lang button,
  .nav:not(.scrolled) .lang button,
  .nav.scrolled .lang button {
    color: #0B1220 !important;
  }
  .nav .lang button.on {
    color: #0B1220 !important;
  }
  .nav.open .nav-links {
    background: rgba(251,247,240,.985) !important;
  }
  .nav.open .nav-links a {
    color: #0B1220 !important;
  }
}



/* Desktop header polish: logo flush left + balanced, stretched navigation */
@media (min-width: 1001px) {
  .nav .wrap{
    width:100%;
    max-width:none;
    padding:0 28px 0 24px;
    gap:28px;
  }

  .logo{
    flex:0 0 auto;
    margin:0;
    width:auto;
  }

  .logo-mark{
    height:56px;
    max-width:260px;
  }

  .nav.scrolled .logo-mark{
    height:46px;
    max-width:220px;
  }

  .nav-links{
    flex:1 1 auto;
    width:auto;
    margin:0;
    padding:0 18px;
    display:flex;
    align-items:center;
    justify-content:space-between;
    gap:8px;
  }

  .nav-links li{
    flex:1 1 0;
    display:flex;
    justify-content:center;
  }

  .nav-links a{
    width:100%;
    text-align:center;
    padding:12px 10px;
    white-space:nowrap;
    border-radius:8px;
    transition:background .2s,color .2s,transform .2s;
  }

  .nav-links a:hover{
    background:rgba(198,161,90,.10);
    transform:translateY(-1px);
  }

  .nav-right{
    flex:0 0 auto;
    gap:12px;
  }

  .lang button{
    min-width:48px;
    height:42px;
    padding:0 12px;
  }

  .nav-cta{
    min-width:170px;
    min-height:48px;
    padding:12px 24px;
    font-size:14px;
    border-radius:9px;
  }
}



.file-upload{display:flex;align-items:center;gap:12px;min-height:62px;padding:10px 14px;border:1px solid var(--line,#ddd);border-radius:8px;background:rgba(255,255,255,.28)}
.file-native{position:absolute!important;width:1px!important;height:1px!important;padding:0!important;margin:-1px!important;overflow:hidden!important;clip:rect(0,0,0,0)!important;white-space:nowrap!important;border:0!important}
.file-btn{display:inline-flex;align-items:center;justify-content:center;min-height:40px;padding:9px 16px;border:1px solid #c6a15a;border-radius:7px;background:#fff;color:#0b1220;font-weight:700;cursor:pointer;white-space:nowrap}
.file-btn:hover{background:#f6ecd6}
.file-name{min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;color:var(--text,#4b5563)}
@media(max-width:640px){.file-upload{align-items:stretch;flex-direction:column}.file-btn{width:100%}.file-name{text-align:center}}



/* --- Custom multilingual date picker (PL / UA / EN) --- */
.dp{position:relative}
.dp-input{width:100%;cursor:pointer;padding-right:42px!important}
.dp-toggle{position:absolute;right:8px;top:50%;transform:translateY(-50%);background:none;border:0;cursor:pointer;padding:5px;line-height:0;color:#5C6570;display:flex;border-radius:6px;transition:.15s}
.dp-toggle:hover{background:var(--acc-soft)}
.dp-toggle svg{width:20px;height:20px}
.dp-cal{position:absolute;z-index:60;top:calc(100% + 6px);left:0;width:300px;max-width:calc(100vw - 40px);background:#fff;border:1px solid rgba(198,161,90,.35);border-radius:12px;box-shadow:0 20px 50px -16px rgba(20,26,36,.45);padding:14px;font-family:'Source Sans 3',sans-serif}
.dp-cal[hidden]{display:none}
.dp-head{display:flex;align-items:center;gap:8px;margin-bottom:10px}
.dp-title{flex:1;text-align:center;font-family:'Manrope',sans-serif;font-weight:700;font-size:15px;color:var(--text);text-transform:capitalize}
.dp-nav{width:30px;height:30px;flex:0 0 auto;display:flex;align-items:center;justify-content:center;background:none;border:1px solid var(--line);border-radius:6px;cursor:pointer;color:var(--text);font-size:18px;line-height:1;transition:.15s}
.dp-nav:hover{background:var(--acc-soft);border-color:var(--acc)}
.dp-grid{display:grid;grid-template-columns:repeat(7,1fr);gap:2px}
.dp-wd{text-align:center;padding:6px 0;font-size:11.5px;font-weight:700;color:var(--text-2);text-transform:uppercase;letter-spacing:.03em}
.dp-day{aspect-ratio:1;display:flex;align-items:center;justify-content:center;border:0;background:none;border-radius:7px;cursor:pointer;font-family:inherit;font-size:14px;color:var(--text);transition:.12s}
.dp-day:hover{background:var(--acc-soft)}
.dp-day.dp-oth{color:var(--ink-3);opacity:.45}
.dp-day.dp-today{box-shadow:inset 0 0 0 1.5px var(--acc)}
.dp-day.dp-sel{background:linear-gradient(135deg,#F0D9A2,#C6A15A 55%,#B08A42);color:#0B1220;font-weight:700}
.dp-day.dp-sel:hover{background:linear-gradient(135deg,#F7E6BB,#E4C98A)}
.dp-foot{display:flex;justify-content:space-between;margin-top:10px;padding-top:10px;border-top:1px solid var(--line)}
.dp-link{background:none;border:0;cursor:pointer;font-family:inherit;font-size:13px;font-weight:600;color:var(--acc);padding:4px 8px;border-radius:6px;transition:.15s}
.dp-link:hover{background:var(--acc-soft)}

/* Make "Szukam pracy" gold, matching the gold "Zamów pracowników" CTA */
a[data-i="h_cta2"], button[data-i="tab2"], .tab[data-i="tab2"] {
  background: linear-gradient(135deg,#F0D9A2,#C6A15A 55%,#B08A42) !important;
  color:#0B1220 !important;
  border-color:#C6A15A !important;
